const CASH_SETTLEMENT_CSS="/* Richer pot and settlement animations: displayed money remains server-owned. */\n.cash-pot .cash-layer{filter:drop-shadow(1px 4px 3px #30210e55)}\n.cash-burst-flight{position:fixed;top:0;left:0;width:67px;height:48px;pointer-events:none;z-index:1510;filter:drop-shadow(0 5px 4px #0007);animation:cash-burst-arc 820ms cubic-bezier(.24,.6,.32,1) both;will-change:transform,opacity}\n.cash-pot-ghost{position:fixed;z-index:1500;pointer-events:none;display:grid;place-items:center;animation:cash-pot-drain 650ms ease-in both}\n.cash-receipt{position:fixed;z-index:1550;width:220px;max-width:calc(100vw - 16px);display:flex;flex-direction:column;align-items:center;gap:3px;padding:9px 12px;border:1px solid #e7be6d;border-radius:11px;background:linear-gradient(135deg,#62431aee,#24170ff2);color:#fff1c6;box-shadow:0 0 0 2px #4a2b12,0 5px 24px #0006;pointer-events:none;animation:cash-receipt-pop 260ms cubic-bezier(.2,.9,.2,1.25) both;text-align:center;font-family:system-ui}\n.cash-receipt strong{font-size:16px;font-weight:800;max-width:100%;overflow-wrap:anywhere}.cash-receipt span{font-size:19px;font-weight:900;color:#ffe187;text-shadow:0 2px #3d270f}.cash-receipt.cash-refund{background:linear-gradient(135deg,#254c4be8,#172a2bea);border-color:#91b7a5}.cash-receipt.cash-refund span{color:#c5e2d4}\n.cash-winner-arrival .profile-avatar{animation:cash-winner-glow 700ms ease-out 2}.cash-winner-arrival .cash-pile{animation:cash-wallet-hit 550ms ease-out 2}.pot-chips-in .cash-pile{animation:cash-pot-grow 850ms ease-out both}\n@keyframes cash-burst-arc{0%{transform:translate(calc(var(--from-x) - 33px),calc(var(--from-y) - 24px)) rotate(var(--cash-spin)) scale(.65);opacity:0}12%{opacity:1}45%{transform:translate(calc(var(--mid-x) - 33px),calc(var(--mid-y) - 24px)) rotate(calc(var(--cash-spin) * -1)) scale(1.08);opacity:1}85%{opacity:1}100%{transform:translate(calc(var(--to-x) - 33px),calc(var(--to-y) - 24px)) rotate(var(--cash-spin)) scale(.64);opacity:0}}\n@keyframes cash-pot-drain{0%,20%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(.65)}}\n@keyframes cash-receipt-pop{0%{opacity:0;transform:translateY(13px) scale(.8)}75%{opacity:1;transform:translateY(-3px) scale(1.025)}100%{opacity:1;transform:translateY(0) scale(1)}}\n@keyframes cash-winner-glow{0%,100%{filter:brightness(1);transform:scale(1)}35%{filter:brightness(1.35) drop-shadow(0 0 13px #ffe58a);transform:scale(1.09)}}\n@keyframes cash-wallet-hit{0%,100%{transform:translateY(0) scale(1)}32%{transform:translateY(-6px) scale(1.12)}65%{transform:translateY(2px) scale(.98)}}\n@keyframes cash-pot-grow{0%,65%{transform:scale(1)}80%{transform:scale(1.08)}100%{transform:scale(1)}}\n@media (max-width:700px){.cash-receipt{width:180px;padding:7px 9px}.cash-receipt strong{font-size:13px}.cash-receipt span{font-size:16px}.cash-burst-flight{width:54px;height:40px}}\n@media (prefers-reduced-motion:reduce){.cash-burst-flight,.cash-pot-ghost{display:none}.cash-receipt,.cash-winner-arrival .profile-avatar,.cash-winner-arrival .cash-pile,.pot-chips-in .cash-pile{animation:none}}\n\n.turn-clock-critical{color:#ffe0af!important;background:#7f251a!important;border-color:#ffb55c!important;border-radius:7px;text-shadow:0 1px #43100c;animation:turn-last-five 1s ease-in-out infinite}\n[data-table-clock].turn-clock-critical,#turn-clock.turn-clock-critical{font-size:23px!important;font-weight:900;padding:5px 12px!important;min-width:60px;text-align:center}#seotda-clock.turn-clock-critical,#badugi-clock.turn-clock-critical{font-size:16px!important;font-weight:900;padding:4px 8px}\n@keyframes turn-last-five{0%,100%{box-shadow:0 0 0 1px #e88b4d,0 0 3px #dc642e77;transform:scale(1)}40%{box-shadow:0 0 0 2px #f1b265,0 0 14px #ed783499;transform:scale(1.06)}}\n@media (max-width:700px){[data-table-clock].turn-clock-critical,#turn-clock.turn-clock-critical{font-size:18px!important;padding:4px 8px!important}}\n@media (prefers-reduced-motion:reduce){.turn-clock-critical{animation:none}}\n\n/* Keep clocks steady: no pulsing/scale/font-size changes as seconds pass. */\n.clock,#turn-clock,#seotda-clock,#badugi-clock,[data-table-clock],.table-turn-banner,.turn-bar{animation:none!important;transition:none!important;transform:none!important;font-variant-numeric:tabular-nums}\n.clock,#turn-clock,[data-table-clock],.clock.turn-clock-critical,#turn-clock.turn-clock-critical,[data-table-clock].turn-clock-critical{display:inline-flex;align-items:center;justify-content:center;box-sizing:border-box;min-width:64px;width:64px;height:30px;min-height:30px;padding:3px 7px!important;font-size:13px!important;line-height:20px;white-space:nowrap}\n#seotda-clock,#badugi-clock,#seotda-clock.turn-clock-critical,#badugi-clock.turn-clock-critical{font-size:12px!important;line-height:20px;min-height:26px;min-width:125px;padding:3px 7px!important;white-space:nowrap;box-sizing:border-box}\n.turn-clock-critical{animation:none!important;transform:none!important;box-shadow:0 0 0 1px #e6a85c!important}\n@media (max-width:700px){.clock,#turn-clock,[data-table-clock],.clock.turn-clock-critical,#turn-clock.turn-clock-critical,[data-table-clock].turn-clock-critical{min-width:54px;width:54px;height:28px;min-height:28px;font-size:12px!important}}\n\n.clock.turn-clock-critical,#turn-clock.turn-clock-critical,[data-table-clock].turn-clock-critical{font-size:13px!important;width:64px;height:30px;min-width:64px;min-height:30px;animation:none!important;transition:none!important;transform:none!important}\n#seotda-clock.turn-clock-critical,#badugi-clock.turn-clock-critical{font-size:12px!important;animation:none!important;transition:none!important;transform:none!important}\n@media (max-width:700px){.clock.turn-clock-critical,#turn-clock.turn-clock-critical,[data-table-clock].turn-clock-critical{font-size:12px!important;width:54px;height:28px;min-width:54px;min-height:28px}}\n";
function ensureTablePresentation(){if(document.getElementById('hodon-table-presentation-v53'))return;const style=document.createElement('style');style.id='hodon-table-presentation-v53';style.textContent=TABLE_PRESENTATION_CSS+SEOTDA_COMPACT_CSS+CASH_SETTLEMENT_CSS;document.head.append(style);document.documentElement.dataset.tablePresentation='v53';}
